973	\subsection{Integrated left-right asymmetry (${\cal A}_{\rm LR}$)} 
974	
975	We also calculate the integrated $\mathcal{A}_{\rm{LR}}$ by integrating Eq.~\ref{ALR-d-A} over the scattering angle: 
976	\begin{align}
977	 \mathcal{A}_{\rm LR}
978	 & \ = \ \frac{\sigma^{\rm LR}-\sigma^{\rm RL}}
979	 {\sigma^{\rm LR}+ \sigma^{\rm RL}}.
980	\label{ALRx}
981	\end{align}
982	In terms of the gauge couplings of the fermions, we can write Eq.~\ref{ALRx} as
983	\bea
984	 \mathcal{A}_{\rm LR} 
985	 \ = \ \frac{\splitfrac{\Big( 1 + \frac{1}{3}\beta^{2} \Big) 
986	 \Big[  \big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2} \big)
987	 -  \big( |q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2} \big) \Big]}{
988	 + 8 \frac{m_{f}^{2}}{s} \Big[ {\rm Re}(q^{e_{L}f_{L}} {q^{e_{L} f_{R}}}^{\ast})
989	- {\rm Re}( q^{e_{R} f_{R}} {q^{e_{R} f_{L}}}^{\ast}) \Big]}}{\splitfrac{\Big( 1 + \frac{1}{3}\beta^{2} \Big) 
990	 \Big[  \big( |q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2} \big)
991	 +  \big( |q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2} \big) \Big]}{ + 8 \frac{m_{f}^{2}}{s} \Big[ {\rm Re}(q^{e_{L}f_{L}} {q^{e_{L} f_{R}}}^{\ast})
992	+ {\rm Re}( q^{e_{R} f_{R}} {q^{e_{R} f_{L}}}^{\ast}) \Big]}} \, .
993	\label{Eq:A_LR-Qs}
994	\eea
995	In the limit $m_{f} \ll \sqrt{s}$, Eq.~\ref{Eq:A_LR-Qs} is reduced to
996	\begin{align}
997	 \mathcal{A}_{\rm LR}
998	 & \ \simeq \  
999	\frac{
1000	(|q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2})
1001	 - (|q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2})
1002	}{
1003	(|q^{e_{L} f_{L}}|^{2} + |q^{e_{L} f_{R}}|^{2})
1004	 + (|q^{e_{R} f_{R}}|^{2} + | q^{e_{R} f_{L}}|^{2})
1005	} \, .
1006	\label{ALR-No-mf}
1007	\end{align}
1008	The observable integrated $\mathcal{A}_{\rm{LR}}$ as a function of the electron and positron beam polarizations is given by 
1009	\begin{align}
1010	\mathcal{A}_{\rm LR}(P_{e^-},P_{e^+})
1011	\  = \  \frac{
1012	 \sigma(P_{e^-},P_{e^+})
1013	 -\sigma(-P_{e^-},-P_{e^+})
1014	 }
1015	 {
1016	 \sigma(P_{e^-},P_{e^+})
1017	 +\sigma(-P_{e^-},-P_{e^+})
1018	 } \, ,
1019	\label{ALR-obs}
1020	\end{align}
1021	for $P_{e^-}<0$ and $|P_{e^-}|>|P_{e^+}|$. This is related to Eq.~\ref{ALRx} by
1022	\bea
1023	\mathcal{A}_{\rm LR} \ = \ \frac{1}{P_{\rm eff}}
1024	\mathcal{A}_{\rm LR}(P_{e^-},P_{e^+}) \, .
1025	\label{difA}
1026	\eea
