1042	\begin{align}
1043	 \mathcal{A}_{\rm LR}^{x_H=-2}
1044	 &\ \simeq \  
1045	\frac{
1046	(|q^{e_{L} \mu_{L}}_{\rm{SM}}|^{2} + |q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2})
1047	 - (|q^{e_{R} \mu_{R}}|^{2} + | q^{e_{R} \mu_{L}}_{SM}|^{2})
1048	}{
1049	(|q^{e_{L} \mu_{L}}_{\rm{SM}}|^{2} + |q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2})
1050	 + (|q^{e_{R} \mu_{R}}|^{2} + | q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2})
1051	} \, ,  \\
1052	 \mathcal{A}_{\rm LR}^{x_H=-1}
1053	 & \ \simeq \  
1054	\frac{
1055	(|q^{e_{L} \mu_{L}}|^{2} + |q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2})
1056	 - (|q^{e_{R} \mu_{R}}_{\rm{SM}}|^{2} + | q^{e_{R} \mu_{L}}_{SM}|^{2})
1057	}{
1058	(|q^{e_{L} \mu_{L}}|^{2} + |q^{e_{L} \mu_{R}}_{\rm{SM}}|^{2})
1059	 + (|q^{e_{R} \mu_{R}}|^{2} + | q^{e_{R} \mu_{L}}_{\rm{SM}}|^{2})
1060	} \, .
1061	\label{ALR-No-mf-1}
1062	\end{align}
1063	In case of the other $x_H$ charges the BSM contributions come from all $q^{\rm{XY}}$. 
1064	
1065	From Eq.~\ref{Eq:A_LR-Qs} and Table~\ref{tabASM} we can write the integrated LR asymmetry for $e^-e^+ \to b\overline{b}$ process at $x_H=-1$ and $1$ as 
1066	\begin{align}
1067	 \mathcal{A}_{\rm LR}^{x_H=-1}
1068	 & \ \simeq \  
1069	\frac{
1070	(|q^{e_{L} b_{L}}|^{2} + |q^{e_{L} b_{R}}|^{2})
1071	 - (|q^{e_{R} b_{R}}_{\rm{SM}}|^{2} + | q^{e_{R} b_{L}}_{\rm{SM}}|^{2})
1072	}{
1073	(|q^{e_{L} b_{L}}|^{2} + |q^{e_{L} b_{R}}|^{2})
1074	 + (|q^{e_{R} b_{R}}_{\rm{SM}}|^{2} + | q^{e_{R} b_{L}}_{\rm{SM}}|^{2})
1075	} \, , \\
1076	 \mathcal{A}_{\rm LR}^{x_H=1}
1077	 &\ \simeq \  
1078	\frac{
1079	(|q^{e_{L} b_{L}}|^{2} + |q^{e_{L} b_{R}}_{\rm{SM}}|^{2})
1080	 - (|q^{e_{R} b_{R}}_{\rm{SM}}|^{2} + | q^{e_{R} b_{L}}|^{2})
1081	}{
1082	(|q^{e_{L} b_{L}}|^{2} + |q^{e_{L} b_{R}}_{\rm{SM}}|^{2})
1083	 + (|q^{e_{R} b_{R}}_{\rm{SM}}|^{2} + |q^{e_{R} b_{L}}|^{2})
1084	} \, .
1085	\label{ALR-No-mf-3}
1086	\end{align}
1087	The BSM contributions are from the $|q^{XY}|$ quantities. For $x_H=2$ the contribution will come from all $|q^{\rm{XY}}|$. Similar behavior will be observed for the $t\overline{t}$ process where the BSM contributions will be associated with the choices of $x_H$ following Table~\ref{tabASM}. 
1088	From Fig.~\ref{ALR-1-2}, we see that for all the fermion pair-production processes, the $x_H=-1$ case is close to the SM, whereas other $x_H$ charges can lead to significant differences with respect to the SM prediction.
1089	
1090	The amount of deviation from the SM in the integrated LR asymmetry can be defined as
1091	\begin{align}
1092	\Delta_{\mathcal{A}_{\rm LR}} =
1093	\frac{\mathcal{A}_{\rm LR}^{U(1)_X}}{\mathcal{A}_{\rm LR}^{\rm SM}}-1\, ,
1094	\label{DeltaALR}
1095	\end{align}
1096	respectively
1097	
1098	\begin{figure}[t!]
1099	\begin{center}
1100	\includegraphics[scale=0.13]{IntDevALRmumu.pdf} 
1101	\includegraphics[scale=0.13]{IntDevALRbb.pdf} 
1102	\includegraphics[scale=0.13]{IntDevALRtt.pdf} 
1103	\caption{The deviations in integrated LR asymmetry for the process $e^-e^+ \to f \overline{f}$ as a function of $\sqrt s$ for $M_{Z^\prime}=7.5$ TeV. The contribution from theoretically estimated statistical deviations are shown by gray shaded band.}
1104	\label{ALR-1-2-3}
1105	\end{center}
1106	\end{figure}
1107	
1108	which is shown in Fig.~\ref{ALR-1-2-3} as a function of the center-of-mass energy for the $\mu^+\mu^-$ (left), $b\overline{b}$ (middle) and $t\overline{t}$ (right) final states. The gray-shaded band shows the theoretically estimated statistical uncertainty (cf.~Eq.~\ref{Eq:Error-A_LR-1-1}). At $\sqrt s=250$ GeV, the deviation in the $\mu^+\mu^-$ process can reach up to $1.5\%$, $3.1\%$ and $8.3\%$ for $x_H=-2,$ $1$, $2$ respectively whereas that for $x_H=-1$ is below $1\%$. The deviations for the $\mu^+\mu^-$ process at 500 GeV can be $6.7\%$, $1.5\%$, $14\%$ and $38\%$ for $x_H=-2$, $-1$, $1$ and $2$ respectively. The deviations increase up to $28\%$, $6.6\%$, $62\%$ and $>100\%$ for $x_H=-2$, $-1$, $1$ and $2$ respectively at $1$ TeV, and become very large at $3$ TeV. Hence for the $\mu^+\mu^-$ final state $\Delta_{A_{\rm{LR}}}$ will be a very useful variable depending on the choice of $x_H$ and $\sqrt{s}$. 
1109	
1110	The corresponding deviations for the $b\overline{b}$ process are much smaller: below $1\%$ at $250$ GeV for all $x_H$ and within the theoretically estimated statistical error (similarly for the $500$ GeV and $1$ TeV colliders). The deviations will be roughly within $20\%-40\%$ at $3$ TeV collider for all $x_H$ except $x_H=-1$. As for the $t\overline{t}$ final state, the deviations can be $1.7\%$, $2.4\%$ and $6.5\%$ for $x_H=-2$, $1$ and $2$ respectively at 500 GeV. At 1 TeV these values reach up to $8.1\%$, $11\%$ and $32\%$ for $x_H=-2$, $1$ and $2$ respectively. We find the deviation for $x_H=-1$ is throughout below $1\%$. 
